import{_ as p,a0 as o,w as d,s as r,ao as l,I as a,x as i,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Arch Linux 中安装 GNOME 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安装 GNOME 桌面 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安装 GNOME 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安装 GNOME 桌面 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221105.3 ⭐️⭐️ How to Install GNOME Desktop in Arch Linux [Complete Guide]","title":"如何在 Arch Linux 中安装 GNOME 桌面","tag":"202302","desc":""},"relativePath":"202302/20221105.3 ⭐️⭐️ How to Install GNOME Desktop in Arch Linux [Complete Guide].md","filePath":"[post].md"}'),h={name:"202302/20221105.3 ⭐️⭐️ How to Install GNOME Desktop in Arch Linux [Complete Guide].md"};function g(c,s,u,k,b,m){const e=o("Link");return d(),r("div",null,[s[23]||(s[23]=l('<h1 id="如何在-arch-linux-中安装-gnome-桌面" tabindex="-1">如何在 Arch Linux 中安装 GNOME 桌面 <a class="header-anchor" href="#如何在-arch-linux-中安装-gnome-桌面" aria-label="Permalink to “如何在 Arch Linux 中安装 GNOME 桌面”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/13/220203a5yb5xy24yer4atv.jpg" alt=""></p><blockquote><p>本指南解释了在 Arch Linux 中安装 GNOME 桌面所需的步骤。</p></blockquote><p>本指南有两部分：第一部分是关于安装基本的 Arch 系统；第二部分是在 Arch Linux 基础上安装完整的 GNOME 桌面环境。</p><h3 id="什么是-gnome-桌面" tabindex="-1">什么是 GNOME 桌面？ <a class="header-anchor" href="#什么是-gnome-桌面" aria-label="Permalink to “什么是 GNOME 桌面？”">​</a></h3><p>GNOME 是一个流行的桌面环境，是如 Ubuntu 和 Fedora 等许多基于桌面的顶级 Linux 发行版的默认桌面。几乎所有的定制版都提供了一个 GNOME 桌面版本。</p><p>GNOME 桌面是稳定和用户友好的桌面之一，因此它被许多普通和高级用户所青睐。如果你想要一个在你进行工作时保持隐形的桌面，GNOME 就是这样的一个。它不会在你工作时妨碍你。因此，尽管有许多关于 GNOME 3（目前的版本）速度慢、资源重等争议，它仍然是许多人的流行和默认选择。</p><p>说了这么多，让我们来看看如何在裸机 Arch 中安装 GNOME 桌面。</p><h3 id="在-arch-linux-中安装-gnome-桌面" tabindex="-1">在 Arch Linux 中安装 GNOME 桌面 <a class="header-anchor" href="#在-arch-linux-中安装-gnome-桌面" aria-label="Permalink to “在 Arch Linux 中安装 GNOME 桌面”">​</a></h3><h4 id="第一部分-安装-arch-linux" tabindex="-1">第一部分：安装 Arch Linux <a class="header-anchor" href="#第一部分-安装-arch-linux" aria-label="Permalink to “第一部分：安装 Arch Linux”">​</a></h4><p>如果你已经安装了 Arch Linux，你可以跳过这一步，直接进入下面安装 GNOME 桌面部分。</p>',11)),a("p",null,[s[1]||(s[1]=i("要快速安装 Arch Linux 基础版，请遵循以下步骤。你也可以访问 ",-1)),n(e,{href:"https://www.debugpoint.com/2020/11/install-arch-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("该指南",-1)])]),_:1}),s[2]||(s[2]=i("，了解如何将 Arch Linux 安装为双启动或在虚拟机中的完整教程。",-1))]),s[24]||(s[24]=a("p",null,[i("本文下面介绍的步骤是安装 Arch 的传统方式。新手请按照下面的指南链接，以更现代的方式使用 "),a("code",null,"archinstall"),i(" 脚本。完成后，回来通过第二部分的步骤继续 GNOME 安装。")],-1)),a("blockquote",null,[a("p",null,[a("strong",null,[n(e,{href:"https://www.debugpoint.com/archinstall-guide/"},{default:t(()=>[...s[3]||(s[3]=[i("现代方式：使用 archinstall 脚本安装（推荐）",-1)])]),_:1})])])]),s[25]||(s[25]=a("h5",{id:"传统方式-下载-arch-linux",tabindex:"-1"},[i("传统方式：下载 Arch Linux "),a("a",{class:"header-anchor",href:"#传统方式-下载-arch-linux","aria-label":"Permalink to “传统方式：下载 Arch Linux”"},"​")],-1)),s[26]||(s[26]=a("p",null,"从下面的链接下载 Arch Linux 的 .iso 文件。它也提供了磁力链接和种子链接。下载后，将 ISO 写入 USB 驱动器。然后从该驱动器启动。",-1)),a("blockquote",null,[a("p",null,[a("strong",null,[n(e,{href:"https://www.archlinux.org/download/"},{default:t(()=>[...s[4]||(s[4]=[i("下载 Arch Linux",-1)])]),_:1})])])]),s[27]||(s[27]=l(`<p>如果你打算通过 GNOME Boxes、virt-manager 把它安装成一个虚拟机镜像，那么你就不需要把它写入 U 盘。</p><h5 id="启动和配置分区" tabindex="-1">启动和配置分区 <a class="header-anchor" href="#启动和配置分区" aria-label="Permalink to “启动和配置分区”">​</a></h5><p>从 Arch Linux ISO 启动后，你必须运行一系列的命令来安装基本系统。</p><p>首先，运行下面的命令，找出设备标识符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk -l</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/fdisk-l-before.jpg" alt="之前的 fdisk -l"></p><p>然后用设备标识符，运行下面的命令，开始对你的磁盘进行分区。请确保根据你的系统改变 <code>/dev/sda</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cfdisk /dev/sda</span></span></code></pre></div><p>在下一个提示中选择 <code>label type = dos</code>。</p><p>选择自由空间，并从底部选择 “<ruby>新建<rt>New</rt></ruby>” 选项。在这个例子中，我将创建三个分区，如下图所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/sda1 - 1G - for /boot</span></span>
<span class="line"><span>/dev/sda2 - 5G - for root</span></span>
<span class="line"><span>/dev/sda3 - 1G - for swap</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/cfdisk-1024x159.jpg" alt="cfdisk"></p><p>在下一个屏幕中，提供引导分区的分区大小（在这个例子中，我给出了 1GB）。选择它作为主分区。</p><p>对大小为 5GB 的主根分区重复同样的步骤。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Swap-parition-type-change.jpg" alt="改变为交换分区类型"></p><p>用同样的步骤创建一个大小为 1G 的交换分区（你可以根据你的需要改变它）。创建交换分区后，确保在底部选择 “<ruby>类型<rt>Type</rt></ruby>”，并用 “Linux Swap/Solaris” 选项将其标记为交换分区。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/final-partition-list-in-cfdisk-1024x178.jpg" alt="cfdisk 中的最终分区列表"></p><p>一旦完成，使用底部的 “<ruby>写入<rt>Write</rt></ruby>” 选项将变化写入磁盘。<strong>确保你在写入前做了备份，因为这是你系统中的一个永久性变化。</strong></p><p>在你继续之前，运行下面的命令来检查。你可以看到在这个例子中，有三个分区被列出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk -l</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/final-partition-list-in-fdisk.jpg" alt="fdisk 中的最终分区列表"></p><p>依次运行下面的命令，在上面新创建的分区中格式化并创建一个 ext4 文件系统。请确保你根据你的需要改变 <code>/dev/sda1</code> 和 <code>/dev/sda2</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs.ext4 /dev/sda1</span></span>
<span class="line"><span>mkfs.ext4 /dev/sda2</span></span>
<span class="line"><span>mkswap /dev/sda3</span></span>
<span class="line"><span>swapon /dev/sda3</span></span></code></pre></div><p>完成后，装载系统并创建必要的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount /dev/sda2 /mnt</span></span>
<span class="line"><span>mkdir /mnt/boot /mnt/var /mnt/home</span></span>
<span class="line"><span>mount /dev/sda1 /mnt/boot</span></span></code></pre></div><p>同样，确保你根据你的系统改变 <code>/dev/sda1</code>、<code>/dev/sda2</code> 和 <code>/dev/sda3</code>。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/prepare-file-system.jpg" alt="准备文件系统"></p><h5 id="安装基础系统" tabindex="-1">安装基础系统 <a class="header-anchor" href="#安装基础系统" aria-label="Permalink to “安装基础系统”">​</a></h5>`,28)),a("p",null,[s[6]||(s[6]=i("我希望你已经连接到互联网了。如果没有，请尝试使用 USB 网卡或 Arch 安装程序自动配置和检测的有线网络连接。如果你没有可用的有线连接，请按照 ",-1)),n(e,{href:"https://www.debugpoint.com/2020/11/connect-wifi-terminal-linux/"},{default:t(()=>[...s[5]||(s[5]=[i("该指南",-1)])]),_:1}),s[7]||(s[7]=i(" 使用 Arch Linux 安装程序配置一个无线或 Wi-Fi 网络。",-1))]),s[28]||(s[28]=l(`<p>依次运行下面的命令，将基本系统安装到已安装的分区中。下载的大小约为 400MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Syy</span></span>
<span class="line"><span>pacstrap /mnt base base-devel linux linux-firmware nano dhcpcd net-tools grub</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Install-base-system-1024x205.jpg" alt="安装基本系统"></p><p>一旦完成，就会生成文件系统表，没有它你就无法启动系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>genfstab -U /mnt &gt;&gt; /mnt/etc/fstab</span></span></code></pre></div><h5 id="配置基础系统" tabindex="-1">配置基础系统 <a class="header-anchor" href="#配置基础系统" aria-label="Permalink to “配置基础系统”">​</a></h5><p>依次按照下面的命令来配置基本系统。这涉及到设置你的地域、语言、添加一个登录用户，以及设置互联网：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arch-chroot /mnt</span></span>
<span class="line"><span>nano /etc/locale.gen</span></span></code></pre></div><p>通过去掉开头的 <code>#</code> 来取消对你所选择的 <ruby>语言环境<rt>locale</rt></ruby> 的注释。在本指南中，我选择了 <code>en_US.UTF-8 UTF-8</code>，按 <code>CTRL+O</code>、回车和 <code>CTRL+X</code> 退出 nano。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/change-locale.jpg" alt="本地化"></p><p>使用以下方法生成语言环境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locale-gen</span></span></code></pre></div><p>如果你不想手动去 <code>/etc/locale.gen</code> 设置语言，也可以使用以下命令设置语言：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo LANG=en_US.UTF-8 &gt; /etc/locale.conf</span></span>
<span class="line"><span>export LANG=en_US.UTF-8</span></span></code></pre></div><p>设置当地的时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /usr/share/zoneinfo/America/New_York /etc/localtime</span></span></code></pre></div><p>同样，你可以根据你的需要来选择它们。你可以通过以下命令列出当地的时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /usr/share/zoneinfo</span></span>
<span class="line"><span>ls /usr/share/zoneinfo/America</span></span></code></pre></div><p>设置硬件时钟，创建一个主机名，并使用以下命令依次启用互联网的 DHCP。你可以根据你的想法，将 <code>arindam-pc</code> 改为任何主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hwclock --systohc --utc</span></span>
<span class="line"><span>echo arindam-pc &gt; /etc/hostname</span></span>
<span class="line"><span>systemctl enable dhcpcd</span></span></code></pre></div><p>下一步是设置根用户的密码，创建一个管理员用户，并在 <code>sudoers</code> 文件中添加该用户。</p><p>依次按照下面的命令进行操作。请确保根据你的需要将用户名从 <code>debugpoint</code> 改为其他名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd rootuseradd -m -g users -G wheel -s /bin/bash debugpointpasswd debugpoint</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/create-user.jpg" alt="创建用户"></p><p>打开 <code>sudoers</code> 文件，添加以下几行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano /etc/sudoers</span></span></code></pre></div><p>添加以下几行。由于你已经创建了 <code>root</code> 用户，该条目应该已经有了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root ALL=(ALL) ALL</span></span>
<span class="line"><span>debugpoint ALL=(ALL) ALL</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/update-sudoers-file.jpg" alt="更改 sudoer 文件"></p><p>依次使用如下命令安装 Grub，设置初始化 Ramdisk 环境，卸载系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grub-install /dev/sda </span></span>
<span class="line"><span>grub-mkconfig -o /boot/grub/grub.cfg</span></span>
<span class="line"><span>mkinitcpio -p linux</span></span>
<span class="line"><span>exit</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/configure-grub-1024x639.jpg" alt="配置 Grub"></p><p>然后重新启动你的系统。如果你是在一个物理系统中安装的，在这一步要拔掉 USB 介质。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>umount /mnt/boot</span></span>
<span class="line"><span>umount /mnt</span></span>
<span class="line"><span>reboot</span></span></code></pre></div><p>你现在已经成功地安装了 Arch Linux 基本系统。现在是安装完整的 GNOME 桌面的时候了。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Arch-is-installed.jpg" alt="Arch 安装好了"></p><h4 id="第二部分-在-arch-linux-中安装-gnome" tabindex="-1">第二部分：在 Arch Linux 中安装 GNOME <a class="header-anchor" href="#第二部分-在-arch-linux-中安装-gnome" aria-label="Permalink to “第二部分：在 Arch Linux 中安装 GNOME”">​</a></h4><p>重启后，从 Grub 中选择 Arch Linux。在 Arch Linux 的提示符下，开始依次运行以下命令。这些命令安装 Xorg 服务器、显示管理器、GNOME 桌面组件、控制器包和其他应用程序。</p><p>所有的命令都使用默认值，即在要求时按回车。</p><p>安装 Xorg 服务器。安装大小约为 80MB:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed xorg</span></span></code></pre></div><p>安装显示管理器、GNOME 桌面。安装大小约为 300MB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed gnome gnome-tweaks nautilus-sendto gnome-nettool gnome-usage gnome gnome-multi-writer adwaita-icon-theme xdg-user-dirs-gtk fwupd arc-gtk-theme seahosrse gdm</span></span></code></pre></div><p>上面的安装会要求提供几个软件包的选项。选择你想要的任何一个。如果你不确定，在询问时选择 “jack”、“noto-sans” 和 “xdg-portal-desktop-gnome”。</p><p>安装应用程序。这只是一个参考。你也可以安装你所需要的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed firefox vlc filezilla leafpad xscreensaver archlinux-wallpaper</span></span></code></pre></div><p>现在是时候把显示管理器和网络管理器作为服务启用了。这样，下次登录时，它们就可以由 systemd 自动运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable gdm</span></span>
<span class="line"><span>systemctl enable NetworkManager</span></span></code></pre></div><p>使用 <code>reboot</code> 命令重新启动系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/12/Arch-Linux-Running-GNOME-43-Desktop-1024x636.jpg" alt="Arch Linux 运行 GNOME 43 桌面"></p><p>如果一切顺利，你应该在 GNOME 桌面上看到一个漂亮的登录提示。使用你刚刚创建的凭证登录。迎接你的应该是 Arch Linux 漂亮而干净的 GNOME 43 桌面。</p><p>我希望这个指南能帮助你在裸机 Arch 安装 GNOME 桌面。</p><hr>`,54)),a("p",null,[s[9]||(s[9]=i("via: ",-1)),n(e,{href:"https://www.debugpoint.com/gnome-arch-linux-install/"},{default:t(()=>[...s[8]||(s[8]=[i("https://www.debugpoint.com/gnome-arch-linux-install/",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=i("作者：",-1)),n(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...s[10]||(s[10]=[i("Arindam",-1)])]),_:1}),s[15]||(s[15]=i(" 选题：",-1)),n(e,{href:"https://github.com/lkxed"},{default:t(()=>[...s[11]||(s[11]=[i("lkxed",-1)])]),_:1}),s[16]||(s[16]=i(" 译者：",-1)),n(e,{href:"https://github.com/Chao-zhi"},{default:t(()=>[...s[12]||(s[12]=[i("Chao-zhi",-1)])]),_:1}),s[17]||(s[17]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[i("LCTT",-1)])]),_:1}),s[21]||(s[21]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[i("Linux中国",-1)])]),_:1}),s[22]||(s[22]=i(" 荣誉推出",-1))])])}const y=p(h,[["render",g]]);export{w as __pageData,y as default};
